package za.co.getwiredautoworx.owner;
import android.app.*;import android.os.*;import android.webkit.*;import android.view.*;import android.content.*;import android.net.Uri;
public class MainActivity extends Activity { private WebView web; private ValueCallback<Uri[]> fileCallback; private static final int FILE_REQ=42;
@Override public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);web.setWebViewClient(new WebViewClient());web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){fileCallback=cb;try{startActivityForResult(p.createIntent(),FILE_REQ);}catch(Exception e){cb.onReceiveValue(null);}return true;}});web.loadUrl("https://www.getwiredauto.co.za/admin.html");}
@Override protected void onActivityResult(int r,int c,Intent d){if(r==FILE_REQ&&fileCallback!=null){fileCallback.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(c,d));fileCallback=null;}super.onActivityResult(r,c,d);}
@Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}}